import codecs, _codecs
for name in ('strict', 'ignore', 'replace', 'xmlcharrefreplace', 'backslashreplace', 'namereplace', 'surrogatepass', 'surrogateescape'):
    original = codecs.lookup_error(name)
    for replacement in (original, lambda error: ('?', error.end)):
        codecs.register_error(name, replacement)
        try:
            _codecs._unregister_error(name)
        except ValueError as error:
            print(name, type(error).__name__, error.args, error.__cause__, error.__context__, getattr(error, '__notes__', None), codecs.lookup_error(name) is replacement)
        else:
            raise AssertionError('protected handler removed')
    codecs.register_error(name, original)
for name in ('', 'custom', 'é', 'constructor', '__proto__'):
    print(name, _codecs._unregister_error(name))
    codecs.register_error(name, codecs.lookup_error('strict'))
    print(name, _codecs._unregister_error(name), _codecs._unregister_error(name))
